// Пин светодиода (на большинстве плат ESP32/Arduino он встроенный)
const int ledPin = 2; 

// Интервал таймера в миллисекундах (1000 мс = 1 секунда)
const long interval = 5000; // Таймер сработает каждые 5 секунд

unsigned long previousMillis = 0; // Здесь будет храниться время прошлого срабатывания
int ledState = LOW;               // Текущее состояние светодиода

void setup() {
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, ledState);

  Serial.begin(115200);
  Serial.println("Timer started. Interval is 5 seconds.");
}

void loop() {
  unsigned long currentMillis = millis(); // Получаем текущее время работы платы

  // Проверяем, прошло ли нужное количество миллисекунд
  if (currentMillis - previousMillis >= interval) {
    // Сохраняем время последнего срабатывания
    previousMillis = currentMillis;

    // Если светодиод был выключен — включаем, если включен — выключаем
    if (ledState == LOW) {
      ledState = HIGH;
    } else {
      ledState = LOW;
    }

    // Меняем состояние пина
    digitalWrite(ledPin, ledState);

    // Пишем в монитор порта для отладки (работает в веб-компиляторах)
    Serial.print("Tick at: ");
    Serial.println(currentMillis);
  }

  // ВНИМАНИЕ: Код здесь продолжит выполняться без задержек.
  // Сюда можно добавить чтение кнопок, работу с WiFi и т.д.
}
